import React from 'react';
import { FaUserMd, FaFileMedicalAlt, FaPlus } from 'react-icons/fa';

// --- DATA FOR THE CLINIC (featured property is removed) ---
const pricingPlans = [
  {
    icon: <FaUserMd size={30} />,
    title: 'ONE-TIME CONSULTATION',
    subtitle: 'For a focused session',
    price: '1500',
    priceDetails: '/Per Session',
    features: [
      '60-minute detailed consultation',
      'Initial health assessment',
      'Basic diet chart',
      'Email support for 7 days',
    ],
    buttonText: 'BOOK A SESSION',
  },
  {
    icon: <FaFileMedicalAlt size={30} />,
    title: '3-MONTH PLAN',
    subtitle: 'For consistent progress',
    originalPrice: '12000',
    discount: '25% OFF',
    price: '9000',
    priceDetails: '/3 Months',
    features: [
      'Everything in One-Time Consultation',
      '6 Follow-up sessions (bi-weekly)',
      'Customized weekly diet plans',
      'Lifestyle & habit coaching',
      'WhatsApp & Email support',
    ],
    buttonText: 'CHOOSE 3-MONTH PLAN',
  },
];


// --- Main Pricing Component ---
const Pricing = () => {
  return (
    <section style={styles.pricingSection}>
      <div style={styles.container}>
        {pricingPlans.map((plan, index) => (
          // --- CHANGE 1: REMOVED the conditional logic for the card style ---
          <div key={index} style={styles.card}>
            <div style={styles.iconContainer}>{plan.icon}</div>
            <h2 style={styles.title}>{plan.title}</h2>
            <p style={styles.subtitle}>{plan.subtitle}</p>

            <div style={styles.priceContainer}>
              {plan.originalPrice && (
                <span style={styles.originalPrice}>₹{plan.originalPrice}</span>
              )}
              {plan.discount && (
                <span style={styles.discountBadge}>{plan.discount}</span>
              )}
            </div>

            <p style={styles.price}>
              <span style={styles.currency}>₹</span>
              {plan.price}
              <span style={styles.priceDetails}>{plan.priceDetails}</span>
            </p>

            <h3 style={styles.whatsIncluded}>WHAT'S INCLUDED:</h3>
            <ul style={styles.featuresList}>
              {plan.features.map((feature, i) => (
                <li key={i} style={styles.featureItem}>
                  <span style={styles.checkmark}>✓</span> {feature}
                </li>
              ))}
            </ul>

            {/* --- CHANGE 2: REMOVED the conditional logic for the button style --- */}
            <button style={styles.button}>{plan.buttonText} →</button>
          </div>
        ))}
      </div>
    </section>
  );
};


// --- UPDATED STYLES ---
const styles = {
    pricingSection: {
      backgroundColor: '#1a202c',
      padding: '64px 24px',
      fontFamily: 'sans-serif',
      color: '#e2e8f0',
    },
    container: {
      maxWidth: '1200px',
      margin: '0 auto',
      display: 'flex',
      justifyContent: 'center',
      gap: '32px',
      flexWrap: 'wrap',
    },
    card: {
      backgroundColor: '#2d3748',
      padding: '40px',
      borderRadius: '20px',
      border: '1px solid #4a5568',
      width: '350px',
      display: 'flex',
      flexDirection: 'column',
      textAlign: 'left',
      transition: 'transform 0.3s ease, box-shadow 0.3s ease',
    },
    // --- CHANGE 3: REMOVED the featuredCard style as it's no longer needed ---
    iconContainer: {
      backgroundColor: '#4a5568',
      width: '60px',
      height: '60px',
      borderRadius: '12px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      marginBottom: '24px',
      color: '#a7ffeb',
    },
    title: {
      fontSize: '1.5rem',
      fontWeight: 'bold',
      margin: 0,
      color: '#ffffff',
    },
    subtitle: {
      color: '#a0aec0',
      marginBottom: '24px',
    },
    priceContainer: {
        display: 'flex',
        alignItems: 'center',
        gap: '10px',
        height: '24px',
    },
    originalPrice: {
        fontSize: '1.2rem',
        color: '#a0aec0',
        textDecoration: 'line-through',
    },
    discountBadge: {
        backgroundColor: '#28a745',
        color: '#ffffff',
        padding: '4px 8px',
        borderRadius: '6px',
        fontSize: '0.8rem',
        fontWeight: 'bold',
    },
    price: {
      fontSize: '4rem',
      fontWeight: 'bold',
      margin: '8px 0',
      color: '#ffffff',
    },
    currency: {
        fontSize: '2rem',
        color: '#a0aec0',
        marginRight: '8px',
    },
    priceDetails: {
      fontSize: '1rem',
      fontWeight: 'normal',
      color: '#a0aec0',
    },
    whatsIncluded: {
      color: '#a7ffeb',
      fontSize: '0.9rem',
      fontWeight: 'bold',
      margin: '24px 0 16px 0',
      letterSpacing: '1px',
    },
    featuresList: {
      listStyle: 'none',
      padding: 0,
      margin: 0,
      flexGrow: 1,
    },
    featureItem: {
      marginBottom: '12px',
      display: 'flex',
      alignItems: 'center',
      color: '#e2e8f0',
    },
    checkmark: {
        color: '#a7ffeb',
        marginRight: '12px',
        fontWeight: 'bold',
    },
    // --- CHANGE 4: UNIFIED the button style to be solid for all cards ---
    button: {
      backgroundColor: '#a7ffeb', // Solid background color
      color: '#1a202c', // Dark text color for contrast
      border: '2px solid #a7ffeb', // Keep border for structure
      borderRadius: '12px',
      padding: '16px',
      fontSize: '1rem',
      fontWeight: 'bold',
      cursor: 'pointer',
      marginTop: '32px',
      transition: 'opacity 0.3s ease', // Changed transition
    },
    // --- REMOVED the featuredButton style ---
};

export default Pricing;
